/**
 * Factory token usage — per-leg token-usage publisher (owner directive
 * 2026-10-13: factory glue moves into dmtools-agents as JS agent code; awf
 * workflows become thin callers).
 *
 * JS port of the awf factory-teammate.yml step «Publish leg token usage
 * (fa-tokens ledger -> factory-data)» — byte-extracted into
 * scripts/publish-token-usage.sh by IstiN/dmtools-agentic-workflows#34.
 * Behavior contract is identical:
 *
 *   1. Read the run output (RUN_OUTPUT). Missing/empty → skip (warn).
 *   2. Sum every `fa-tokens: {…}` ledger line (resume-aware: one line per
 *      session segment) — balanced-brace scan so a payload wrapped in a log
 *      line is found whole; invalid payloads are skipped. input/output/
 *      cacheRead are summed; the last-seen model wins. Zero in+out → skip.
 *   3. Leg: the run guard collapses the rework slot into kind="dev", so the
 *      true leg is recovered from the runner-config basename — *rework* →
 *      "rework", else KIND, else "dev".
 *   4. Anchor → key: pr-* passes through; gh-N → issue-N; anything else →
 *      skip (warn).
 *   5. Row (printf field order): {"leg","at","prompt","completion","total",
 *      "cacheRead","model"} — at = UTC ISO-8601 seconds.
 *   6. Bootstrap the factory-data branch from the default-branch head
 *      (422 "already exists" is the normal case), then up to 3 attempts:
 *      GET contents (sha + body), append the row under the key, drop rows
 *      older than 14 days, keep the last 40 per key, drop emptied keys,
 *      PUT Contents API with the existing sha. Conflict → refetch → retry
 *      (sh backoff attempt*2s). Exhausted → warn; rows are decorative and
 *      the next leg retries.
 *
 * Transport mirrors factoryState.js: every command starts with `gh` (the
 * executor whitelists the first token); base64 stays in-shell
 * (`printf %s … | base64` / `--jq .content | base64 -d`) so the JS side
 * never needs a base64 codec.
 *
 * Env/file contract (the sh step's env block; the JSRunner entry reads
 * jobParams.customParams first, these env names as fallback):
 *   RUN_OUTPUT   path of the captured run output (fa-tokens ledger source)
 *   CONFIG       runner config path; basename minus .json decides the leg
 *   KIND         leg kind when the basename has no "rework" (default "dev")
 *   ANCHOR       work anchor: pr-<n> | gh-<n>
 *   REPO         owner/repo of the factory-data target
 *   DATA_BRANCH  target branch (default "factory-data")
 *   DATA_PATH    target path   (default "data/fa-tokens.json")
 *
 * Pure functions carry no IO: the publisher takes { exec, read, sleepMs,
 * log } capturers (factoryState.js convention) so tests mock the transport
 * via loadModule without touching any global.
 */

var ROW_KEEP = 40;              // jq `.[-40:]` tail cap per key
var DEFAULT_WINDOW_DAYS = 14;   // jq cutoff: keep rows newer than now-14d
var DEFAULT_DATA_BRANCH = 'factory-data';
var DEFAULT_DATA_PATH = 'data/fa-tokens.json';
var DEFAULT_ATTEMPTS = 3;       // concurrent-leg PUT conflict absorber

// ── ledger parsing (pure) ────────────────────────────────────────────────────

/**
 * Extracts the JSON payload after an `fa-tokens:` marker by balanced-brace
 * scanning (same discipline as aiTeammateTokenUsageReporter.extractFaPayload,
 * but anchored on the marker regex the sh used: `fa-tokens:[ \t]*(\{)`).
 * Returns the payload substring or null when no complete {...} follows.
 */
function extractFaPayload(text, markerEnd) {
    var start = -1;
    for (var i = markerEnd; i < text.length; i++) {
        var ch = text.charAt(i);
        if (ch === ' ' || ch === '\t') continue;
        if (ch === '{') { start = i; break; }
        return null; // sh regex required the brace right after the marker
    }
    if (start === -1) return null;
    var depth = 0;
    var inString = false;
    var escaped = false;
    for (var j = start; j < text.length; j++) {
        var c = text.charAt(j);
        if (inString) {
            if (escaped) escaped = false;
            else if (c === '\\') escaped = true;
            else if (c === '"') inString = false;
            continue;
        }
        if (c === '"') inString = true;
        else if (c === '{') depth++;
        else if (c === '}') {
            depth--;
            if (depth === 0) return text.substring(start, j + 1);
        }
    }
    return null; // unterminated payload (truncated log) — ignored
}

/**
 * python int(rec.get(k) or 0): null/'' → 0; numeric strings coerced;
 * non-numeric → null (the sh's int() raise → whole record skipped).
 */
function ledgerInt(v) {
    if (v === null || v === undefined || v === '') return 0;
    if (typeof v === 'number') return isFinite(v) ? Math.floor(v) : null;
    var s = String(v).trim();
    if (!/^-?\d+$/.test(s)) return null;
    return parseInt(s, 10);
}

/**
 * Sums every fa-tokens ledger record in the run output.
 * Returns { input, output, cacheRead, model } — model is the last-seen
 * non-empty model ('' when the ledger never carries one).
 */
function parseFaTokensLedger(text) {
    var sums = { input: 0, output: 0, cacheRead: 0, model: '' };
    var body = String(text || '');
    var re = /fa-tokens:/g;
    var m;
    while ((m = re.exec(body)) !== null) {
        var payload = extractFaPayload(body, m.index + m[0].length);
        re.lastIndex = m.index + m[0].length; // non-overlapping, marker-paced
        if (payload === null) continue;
        var rec;
        try { rec = JSON.parse(payload); } catch (e) { continue; }
        if (!rec || typeof rec !== 'object' || Array.isArray(rec)) continue;
        var inp = ledgerInt(rec.input);
        var out = ledgerInt(rec.output);
        var cr = ledgerInt(rec.cacheRead);
        if (inp === null || out === null || cr === null) continue; // int() raise
        sums.input += inp;
        sums.output += out;
        sums.cacheRead += cr;
        if (rec.model) sums.model = String(rec.model); // last-seen wins
    }
    return sums;
}

// ── leg / anchor resolution (pure) ───────────────────────────────────────────

/**
 * The run guard collapses the rework slot into kind="dev" (rework legs run
 * the dev pipeline); recover the true leg from the runner config basename:
 * `basename CONFIG .json` containing "rework" → "rework", else KIND,
 * else "dev".
 */
function resolveLeg(configPath, kind) {
    var base = String(configPath || '').split('/').pop() || '';
    var stem = base.replace(/\.json$/, '');
    if (stem.indexOf('rework') !== -1) return 'rework';
    return String(kind || '') || 'dev';
}

/**
 * pr-* passes through; gh-N → issue-N; anything else → null (skip signal).
 */
function resolveAnchorKey(anchor) {
    var a = String(anchor === null || anchor === undefined ? '' : anchor);
    if (a.indexOf('pr-') === 0) return a;
    if (a.indexOf('gh-') === 0) return 'issue-' + a.slice(3);
    return null;
}

// ── time + row shape (pure) ──────────────────────────────────────────────────

/** `date -u +%Y-%m-%dT%H:%M:%SZ` — UTC ISO-8601, seconds precision. */
function utcStampZ(d) {
    var date = (d instanceof Date) ? d : new Date(d);
    if (isNaN(date.getTime())) return '';
    return date.toISOString().replace(/\.\d{3}Z$/, 'Z');
}

/** Retention cutoff: now − days (default 14) as a Z stamp for `>=` compares. */
function cutoffIso(now, days) {
    var ms = (now instanceof Date) ? now.getTime() : new Date(now).getTime();
    if (isNaN(ms)) ms = Date.now();
    var span = (days || DEFAULT_WINDOW_DAYS) * 24 * 60 * 60 * 1000;
    return utcStampZ(new Date(ms - span));
}

/**
 * The printf row: field order is the contract
 * {"leg","at","prompt","completion","total","cacheRead","model"}.
 */
function buildRow(o) {
    o = o || {};
    var prompt = ledgerInt(o.prompt) || 0;
    var completion = ledgerInt(o.completion) || 0;
    return {
        leg: String(o.leg || ''),
        at: String(o.at || ''),
        prompt: prompt,
        completion: completion,
        total: prompt + completion,
        cacheRead: ledgerInt(o.cacheRead) || 0,
        model: String(o.model || '')
    };
}

// ── merge + retention (pure) — the jq program ────────────────────────────────

// Corrupt shapes degrade to {} exactly like the `jq empty` guard.
function objectOrEmpty(cur) {
    return (cur && typeof cur === 'object' && !Array.isArray(cur)) ? cur : {};
}

// Existing keys in insertion order, with `key` appended when absent.
function orderedKeysOf(src, key) {
    var ordered = [];
    var seen = {};
    for (var k in src) {
        if (Object.prototype.hasOwnProperty.call(src, k) && !seen[k]) {
            seen[k] = true;
            ordered.push(k);
        }
    }
    if (!seen[key]) ordered.push(key);
    return ordered;
}

// Rows at/after the cutoff (Z stamps sort as strings), tail-capped at
// ROW_KEEP. Non-row shapes drop.
function retainedRowsOf(rows, cutoff) {
    var kept = [];
    for (var j = 0; j < rows.length; j++) {
        var r = rows[j];
        if (r && typeof r === 'object' && String(r.at || '') >= cutoff) kept.push(r);
    }
    return kept.slice(-ROW_KEEP);
}

/**
 * `.[$key] = ((.[$key] // []) + [$row])
 *  | with_entries(.value |= (map(select((.at // "") >= $cutoff)) | .[-40:]))
 *  | with_entries(select(.value | length > 0))`
 *
 * Appends under the key, drops rows older than cutoff (string compare —
 * Z stamps sort), keeps the LAST 40 per key, drops emptied keys. Corrupt
 * shapes degrade to {} exactly like the `jq empty` guard.
 */
function mergeTokenRows(cur, key, row, cutoff) {
    var src = objectOrEmpty(cur);
    var next = {};
    var ordered = orderedKeysOf(src, key);
    for (var i = 0; i < ordered.length; i++) {
        var kk = ordered[i];
        var rows = src[kk] || [];
        if (kk === key) rows = rows.concat([row]);
        var kept = retainedRowsOf(rows, cutoff);
        if (kept.length > 0) next[kk] = kept;
    }
    return next;
}

// ── gh command builders (pure strings; gh-first executor whitelist) ─────────

/** Single-quote for the shell, factoryState.js discipline. */
function shellQuote(s) {
    return "'" + String(s).replace(/'/g, "'\\''") + "'";
}

/**
 * Bootstrap the data branch from the default-branch head. `|| true`: the
 * 422 "already exists" is the normal case and the executor throws on
 * non-zero exit.
 */
function bootstrapBranchCommand(repo, branch) {
    return 'gh api -X POST repos/' + repo + '/git/refs' +
        ' -f ref=refs/heads/' + branch +
        ' -f sha="$(gh api repos/' + repo +
        '/git/ref/heads/$(gh api repos/' + repo +
        ' --jq .default_branch) --jq .object.sha)" || true';
}

/** Existing-file sha probe ('Not Found'/throw = first publish). */
function contentsShaCommand(repo, path, branch) {
    return 'gh api repos/' + repo + '/contents/' + path + '?ref=' + branch +
        ' --jq .sha';
}

/** Body probe — decoded in-shell so JS never needs a base64 codec. */
function contentsBodyCommand(repo, path, branch) {
    return 'gh api repos/' + repo + '/contents/' + path + '?ref=' + branch +
        ' --jq .content | base64 -d';
}

var BASE64_CHARS = '[REDACTED:High Entropy String]/';

/** Convert a JS string to an array of UTF-8 byte values (0..255). */
function utf8BytesOf(str) {
    var s = String(str == null ? '' : str);
    var utf8 = encodeURIComponent(s);
    var bytes = [];
    for (var i = 0; i < utf8.length; i++) {
        if (utf8.charAt(i) === '%') {
            bytes.push(parseInt(utf8.substr(i + 1, 2), 16));
            i += 2;
        } else {
            bytes.push(utf8.charCodeAt(i));
        }
    }
    return bytes;
}

/** Pure UTF-8 → Base64 encoder (runtime-agnostic: GraalJS, QuickJS, Node). */
function base64EncodeUtf8(str) {
    var bytes = utf8BytesOf(str);
    var out = '';
    for (var j = 0; j < bytes.length; j += 3) {
        var b0 = bytes[j];
        var has1 = (j + 1) < bytes.length;
        var has2 = (j + 2) < bytes.length;
        var b1 = has1 ? bytes[j + 1] : 0;
        var b2 = has2 ? bytes[j + 2] : 0;
        var triplet = (b0 << 16) | (b1 << 8) | b2;
        out += BASE64_CHARS.charAt((triplet >> 18) & 63) +
            BASE64_CHARS.charAt((triplet >> 12) & 63) +
            (has1 ? BASE64_CHARS.charAt((triplet >> 6) & 63) : '=') +
            (has2 ? BASE64_CHARS.charAt(triplet & 63) : '=');
    }
    return out;
}

/** Build the GitHub Contents API PUT JSON body (`--input <file>` payload). */
function buildContentsPutBody(o) {
    var p = o || {};
    var body = {
        branch: String(p.branch || DEFAULT_DATA_BRANCH),
        message: String(p.message || ''),
        content: base64EncodeUtf8(p.json == null ? '{}' : p.json)
    };
    if (p.sha) body.sha = String(p.sha);
    return body;
}

/**
 * Deterministic temp-file path for `--input` (digits-only suffixes, matching
 * `checkRunStamp.js` `tempBodyPath` convention). Note: two concurrent legs on
 * a shared host landing in the exact same millisecond + attempt share this
 * path; each leg runs in its own job container/step in CI.
 */
function tempPutBodyPath(now, attempt) {
    var ms = (now instanceof Date) ? now.getTime() : new Date(now).getTime();
    if (isNaN(ms)) ms = 0;
    return '/tmp/fa-tokens-put-' + Number(ms) + '-' + Number(attempt || 0) + '.json';
}

/** Contents PUT via `--input <tempPath>`: zero payload bytes in argv (gh-1152). */
function contentsPutInputCommand(repo, path, tempPath) {
    return 'gh api -X PUT repos/' + repo + '/contents/' + path + ' --input ' + tempPath;
}

/** Contents PUT (legacy inline argv builder): message, branch, base64 content, sha. */
function contentsPutCommand(repo, path, o) {
    var cmd = 'gh api -X PUT repos/' + repo + '/contents/' + path +
        ' -f branch=' + (o.branch || DEFAULT_DATA_BRANCH) +
        ' -f message=' + shellQuote(o.message || '') +
        ' -f content="$(printf %s ' + shellQuote(o.json || '{}') + ' | base64)"';
    if (o.sha) cmd += ' -f sha=' + shellQuote(o.sha);
    return cmd;
}

/** Write PUT body to `tempPath`, run `gh api --input`, and best-effort delete in `finally`. */
function tryPutViaInputFile(io, repo, path, tempPath, putOpts) {
    var bodyText = JSON.stringify(buildContentsPutBody(putOpts));
    try {
        io.write({ path: tempPath, content: bodyText });
        io.exec({ command: contentsPutInputCommand(repo, path, tempPath) });
        return true;
    } catch (e) {
        return false;
    } finally {
        if (typeof io.del === 'function') {
            try { io.del({ path: tempPath }); } catch (eDel) { /* best-effort cleanup */ }
        }
    }
}

/** Log a one-time warning when falling back to inline argv PUT on a large payload. */
function warnInlineFallbackIfLarge(io, attempt, putOpts) {
    if (Number(attempt) <= 1 && String(putOpts.json).length >= 96000) {
        io.log('::warning::file_write unavailable — inline argv PUT fallback (E2BIG risk at >=96 KB payloads)');
    }
}

/** Dispatch PUT via `--input` temp file when `io.write` is wired, else inline fallback. */
function putTokenContents(io, repo, path, now, attempt, putOpts) {
    if (io && typeof io.write === 'function') {
        return tryPutViaInputFile(io, repo, path, tempPutBodyPath(now, attempt), putOpts);
    }
    warnInlineFallbackIfLarge(io, attempt, putOpts);
    return tryExec(io && io.exec, contentsPutCommand(repo, path, putOpts));
}

// ── publisher (IO via injected capturers) ────────────────────────────────────

function execOut(exec, command) {
    var res = exec({ command: command });
    return String((res && (res.output || res.stdout)) || res || '').trim();
}

function tryExec(exec, command) {
    if (!exec) return false;
    try { exec({ command: command }); return true; } catch (e) { return false; }
}

// io defaults: a no-op sleep and a no-op log; every capturer rides along so
// the whole shaped io can flow into putTokenContents unchanged.
function publishIoOf(io) {
    io = io || {};
    return {
        exec: io.exec,
        read: io.read,
        write: io.write,
        del: io.del,
        sleepMs: io.sleepMs || function () {},
        log: io.log || function () {}
    };
}

// Target defaults: repo, factory-data branch, fa-tokens path, 3 attempts.
function publishTargetOf(opts) {
    return {
        repo: opts.repo || '',
        branch: opts.dataBranch || DEFAULT_DATA_BRANCH,
        path: opts.dataPath || DEFAULT_DATA_PATH,
        attempts: opts.attempts || DEFAULT_ATTEMPTS
    };
}

// The retention clock: the pinned now (tests), else the live clock.
function publishClockOf(opts) {
    return opts.now ? opts.now : new Date();
}

// Run output text: a missing reader or an unreadable file both degrade to ''
// — the `[ ! -s "${RUN_OUTPUT}" ]` skip signal.
function readRunOutputText(read, path) {
    if (typeof read !== 'function') return '';
    try { return String(read(path) || ''); } catch (e) { return ''; }
}

// The skip contract: a warning line, then the skipped result shape. The
// bad-anchor skip keeps the already-resolved leg (undefined → null).
function skipPublish(log, reason, warning, leg) {
    log('::warning::' + warning);
    return { status: 'skipped', reason: reason, key: null, leg: leg || null, row: null, attempts: 0 };
}

// Zero input+output ledger sums — the no-ledger skip signal.
function isZeroLedger(sums) {
    return sums.input === 0 && sums.output === 0;
}

// Existing-file sha probe; a literal 'Not Found' body (like a throw) means
// first publish — no sha.
function fetchBranchSha(exec, repo, path, branch) {
    var sha = '';
    try { sha = execOut(exec, contentsShaCommand(repo, path, branch)); }
    catch (e) { sha = ''; } // first publish — the file is absent
    return sha.indexOf('Not Found') !== -1 ? '' : sha;
}

// Branch body probe; a throw or an unparseable body merges from {} (the
// `jq empty` guard).
function fetchBranchBody(exec, repo, path, branch) {
    try {
        return JSON.parse(execOut(exec, contentsBodyCommand(repo, path, branch)) || '{}');
    } catch (e) { return {}; }
}

// One GET-sha → merge → PUT cycle: true when the PUT landed, false on
// conflict (the caller refetches and retries).
function putTokenRowAttempt(io, target, now, attempt, key, leg, row, cutoff) {
    var sha = fetchBranchSha(io.exec, target.repo, target.path, target.branch);
    var cur = fetchBranchBody(io.exec, target.repo, target.path, target.branch);
    var next = mergeTokenRows(cur, key, row, cutoff);
    return putTokenContents(io, target.repo, target.path, now, attempt, {
        branch: target.branch,
        message: 'leg tokens — ' + key + ' ' + leg + ' [skip ci]',
        json: JSON.stringify(next),
        sha: sha
    });
}

// Up to `target.attempts` cycles; a conflicting PUT refetches and retries
// (sh backoff: sleep attempt*2s between attempts, never after the last).
// Returns the terminal publish outcome.
function putRowWithRetries(io, target, now, key, leg, row, cutoff, log, sleepMs) {
    for (var attempt = 1; attempt <= target.attempts; attempt++) {
        if (putTokenRowAttempt(io, target, now, attempt, key, leg, row, cutoff)) {
            return { status: 'published', attempts: attempt };
        }
        log('token publish attempt ' + attempt + ' conflicted — refetching');
        if (attempt < target.attempts) sleepMs(attempt * 2000); // sh: sleep $((attempt * 2))
    }
    log('::warning::token publish gave up after ' + target.attempts +
        ' attempts (concurrent writes) — rows are decorative, next legs retry');
    return { status: 'gave-up', attempts: target.attempts };
}

/**
 * Publish one leg's token-usage row.
 *
 * opts: runOutput, configPath, kind, anchor, repo, dataBranch, dataPath,
 *       now (Date|ms|ISO — tests pin the clock), attempts (default 3)
 * io:   exec({command}) → {output|stdout} (throws on failure) — REQUIRED
 *       for any gh traffic; read(path) → string (throws when absent);
 *       sleepMs(ms) (default no-op — the sh sleeps attempt*2 s; the agent
 *       runtime has no blocking sleep, retries refetch anyway);
 *       log(line).
 *
 * Returns { status, reason, key, leg, row, attempts } with status
 * 'published' | 'skipped' | 'gave-up' and reason
 * 'no-run-output' | 'no-ledger' | 'bad-anchor' | null.
 */
function publishTokenUsage(opts, io) {
    opts = opts || {};
    var ioOf = publishIoOf(io);
    var log = ioOf.log;
    var sleepMs = ioOf.sleepMs;
    var target = publishTargetOf(opts);
    var now = publishClockOf(opts);

    // 1) run output — `[ ! -s "${RUN_OUTPUT}" ]` → skip
    var text = readRunOutputText(ioOf.read, opts.runOutput);
    if (!text) {
        return skipPublish(log, 'no-run-output', 'no run output captured — skipping token publish');
    }

    // 2) sums — zero in+out → skip
    var sums = parseFaTokensLedger(text);
    if (isZeroLedger(sums)) {
        return skipPublish(log, 'no-ledger', 'no fa-tokens ledger line in run output — skipping token publish');
    }

    // 3) leg from the runner-config basename (rework recovery)
    var leg = resolveLeg(opts.configPath, opts.kind);

    // 4) anchor → key
    var key = resolveAnchorKey(opts.anchor);
    if (!key) {
        return skipPublish(log, 'bad-anchor',
            'unrecognized anchor \'' + String(opts.anchor || '') +
            '\' — skipping token publish', leg);
    }

    // 5) row (printf field order)
    var row = buildRow({
        leg: leg,
        at: utcStampZ(now),
        prompt: sums.input,
        completion: sums.output,
        cacheRead: sums.cacheRead,
        model: sums.model
    });
    log('leg tokens: ' + key + ' ' + leg +
        ' prompt=' + sums.input +
        ' completion=' + sums.output +
        ' cached=' + sums.cacheRead +
        ' model=' + (sums.model || 'none'));

    // 6) bootstrap the data branch (422 already-exists is the normal case)
    tryExec(ioOf.exec, bootstrapBranchCommand(target.repo, target.branch));

    // 7) up to N attempts: refetch sha+body, merge, PUT — conflicts refetch
    var outcome = putRowWithRetries(ioOf, target, now, key, leg, row,
        cutoffIso(now), log, sleepMs);
    return {
        status: outcome.status,
        reason: null,
        key: key,
        leg: leg,
        row: row,
        attempts: outcome.attempts
    };
}

module.exports = {
    parseFaTokensLedger: parseFaTokensLedger,
    extractFaPayload: extractFaPayload,
    resolveLeg: resolveLeg,
    resolveAnchorKey: resolveAnchorKey,
    utcStampZ: utcStampZ,
    cutoffIso: cutoffIso,
    buildRow: buildRow,
    objectOrEmpty: objectOrEmpty,
    orderedKeysOf: orderedKeysOf,
    retainedRowsOf: retainedRowsOf,
    mergeTokenRows: mergeTokenRows,
    shellQuote: shellQuote,
    base64EncodeUtf8: base64EncodeUtf8,
    buildContentsPutBody: buildContentsPutBody,
    tempPutBodyPath: tempPutBodyPath,
    contentsPutInputCommand: contentsPutInputCommand,
    bootstrapBranchCommand: bootstrapBranchCommand,
    contentsShaCommand: contentsShaCommand,
    contentsBodyCommand: contentsBodyCommand,
    contentsPutCommand: contentsPutCommand,
    tryPutViaInputFile: tryPutViaInputFile,
    putTokenContents: putTokenContents,
    publishIoOf: publishIoOf,
    publishTargetOf: publishTargetOf,
    publishClockOf: publishClockOf,
    readRunOutputText: readRunOutputText,
    skipPublish: skipPublish,
    isZeroLedger: isZeroLedger,
    fetchBranchSha: fetchBranchSha,
    fetchBranchBody: fetchBranchBody,
    putTokenRowAttempt: putTokenRowAttempt,
    putRowWithRetries: putRowWithRetries,
    publishTokenUsage: publishTokenUsage,
    ROW_KEEP: ROW_KEEP,
    DEFAULT_WINDOW_DAYS: DEFAULT_WINDOW_DAYS,
    DEFAULT_DATA_BRANCH: DEFAULT_DATA_BRANCH,
    DEFAULT_DATA_PATH: DEFAULT_DATA_PATH,
    DEFAULT_ATTEMPTS: DEFAULT_ATTEMPTS
};

/**
 * Token usage comment helper.
 *
 * Reads provider usage JSON files written by run-agent.sh (e.g. outputs/story_solution_usage.json)
 * and posts them as Jira comments in the form:
 *
 *   [story_solution]: {"provider":"kimi","total_tokens":12345,...}
 *
 * The helper is provider-agnostic. run-agent.sh records usage files in
 * outputs/token_usage_files.json; this helper reads that manifest and posts a
 * comment for every *_usage.json file it points to.
 *
 * IMPORTANT: This module runs inside the DMTools GraalJS bridge, where Node.js
 * built-ins such as `fs` are NOT available. Use the exposed `file_read` tool.
 */

var OUTPUTS_DIR = 'outputs';
var USAGE_SUFFIX = '_usage.json';
var MANIFEST_NAME = 'token_usage_files.json';

// gh-823: load-time require — a deferred (in-function) require resolves
// against the pack's js/ root only at runtime ("Failed to require module:
// ./trackers.js"); load-time requires resolve file-relative and dmtools
// compile discovers them for the pack closure.
var trackersModule = require('./trackers.js');
var configLoader = null;
try { configLoader = require('../configLoader.js'); } catch (e) { /* unit tests inject their own */ }

function readTextFile(filePath) {
    if (!filePath) {
        return null;
    }
    try {
        var content = file_read({ path: filePath });
        if (content) {
            return content.toString();
        }
    } catch (e) {
        // File missing or unreadable — treat as absent.
    }
    return null;
}

function readJsonFile(filePath) {
    var text = readTextFile(filePath);
    if (!text) {
        return null;
    }
    try {
        return JSON.parse(text);
    } catch (e) {
        console.warn('Failed to parse JSON from ' + filePath + ': ' + (e.message || e));
        return null;
    }
}

function fileNameFromPath(filePath) {
    if (!filePath) {
        return '';
    }
    var idx = filePath.lastIndexOf('/');
    return idx >= 0 ? filePath.substring(idx + 1) : filePath;
}

function findUsageFiles(outputsDir) {
    var manifestPath = outputsDir + '/' + MANIFEST_NAME;
    var manifest = readJsonFile(manifestPath);
    if (Array.isArray(manifest)) {
        return manifest.filter(function(entry) {
            return typeof entry === 'string' && entry.indexOf(USAGE_SUFFIX) !== -1;
        });
    }
    return [];
}

function formatJiraMention(notifierId) {
    if (!notifierId) {
        return '';
    }
    var id = String(notifierId);
    if (id.indexOf('~') !== -1) {
        return '[' + id + ']';
    }
    return '[~accountid:' + id + ']';
}

/**
 * Work around a bug in the DMTools GraalJS bridge (JobJavaScriptBridge):
 * any string tool argument that starts with "[" and ends with "]" gets
 * speculatively parsed as a JSON array. org.json's lenient tokenizer can
 * "succeed" on a leading fragment (e.g. an unquoted bareword) and silently
 * discard everything after the first matching "]", corrupting the rest of
 * the string before it reaches the tool. See IstiN/dmtools-agents#360.
 *
 * Our comment format ("[label]: {...}\nInitiator: [~accountid:...]") is
 * exactly this shape: it starts with "[" (the label) and ends with "]"
 * (the mention). Appending a trailing period breaks the pattern without
 * changing the meaningful content.
 */
function avoidBridgeArrayMisparse(str) {
    if (typeof str !== 'string') {
        return str;
    }
    var trimmed = str.trim();
    if (trimmed.length > 2 && trimmed.charAt(0) === '[' && trimmed.charAt(trimmed.length - 1) === ']') {
        return str + '.';
    }
    return str;
}

function formatUsageComment(filePath, data, initiator, provider) {
    var fileName = fileNameFromPath(filePath);
    // Strip the _usage suffix so the comment label matches the agent name
    // (e.g. outputs/story_acceptance_criteria_usage.json -> [story_acceptance_criteria]: {...})
    // Use string operations instead of a regex literal because the GraalJS
    // bridge in this environment does not always have the regex language enabled.
    var label = fileName;
    var suffixIndex = fileName.lastIndexOf(USAGE_SUFFIX);
    if (suffixIndex !== -1 && fileName.substring(suffixIndex) === USAGE_SUFFIX) {
        label = fileName.substring(0, suffixIndex);
    }
    if (String(provider || '').toLowerCase() === 'ado') {
        // agents#877/#878: ADO comments are posted as Markdown, where "[label]: {json}" is a link-reference
        // definition (stored but never rendered) and "[~accountid:x]" is Jira mention markup, not a mention.
        // Use a bold label + fenced json block and show the initiator as plain text. A real @-mention would
        // need the identity GUID, which the job does not have. (Jira/GitHub keep the format below.)
        var adoComment = '**' + label + '**\n```json\n' + JSON.stringify(data) + '\n```';
        if (initiator) {
            adoComment += '\nInitiator: ' + plainInitiator(initiator);
        }
        return adoComment;
    }
    var comment = '[' + label + ']: ' + JSON.stringify(data);
    var mention = formatJiraMention(initiator);
    if (mention) {
        comment += '\nInitiator: ' + mention;
    }
    return avoidBridgeArrayMisparse(comment);
}

/**
 * The initiator as plain text: an account id / email as given, with Jira mention markup removed when the
 * caller passed an already formatted "[~accountid:x]".
 */
function plainInitiator(initiator) {
    var id = String(initiator).trim();
    var prefix = '[~accountid:';
    if (id.indexOf(prefix) === 0 && id.charAt(id.length - 1) === ']') {
        return id.substring(prefix.length, id.length - 1);
    }
    if (id.charAt(0) === '[' && id.charAt(1) === '~' && id.charAt(id.length - 1) === ']') {
        return id.substring(2, id.length - 1);
    }
    return id;
}

/**
 * The customParams of a job action's params (jobParams.customParams or params.customParams), {} when
 * absent. Call sites that have no tracker object pass this so the usage comment goes through the
 * provider the run selected (customParams.trackerProvider) and not through the Jira default (agents#854).
 * @param {Object|null} params the action params
 * @returns {Object}
 */
function customParamsOf(params) {
    return (params && params.jobParams && params.jobParams.customParams) ||
        (params && params.customParams) || {};
}

/**
 * The project config used to pick the tracker provider: the caller's options.config when given;
 * otherwise, only when the provider is not already pinned by customParams.trackerProvider, the
 * project config (config.tracker.provider) loaded best-effort, so a run that sets the provider only
 * there does not fall through to the Jira default (agents#942). Fail-open: null on any problem.
 * @param {Object} options postTokenUsageComments options
 * @returns {Object|null}
 */
function resolveConfig(options) {
    if (options.config) return options.config;
    var cp = options.customParams || {};
    if (cp.trackerProvider || !configLoader || typeof configLoader.loadProjectConfig !== 'function') return null;
    try {
        return configLoader.loadProjectConfig({ customParams: cp }) || null;
    } catch (e) {
        return null;
    }
}

/**
 * Post token usage comments for the given ticket.
 *
 * @param {string} ticketKey - Jira ticket key to comment on.
 * @param {object} options - Optional settings.
 * @param {string} options.outputsDir - Directory to scan for *_usage.json files (default: outputs).
 * @param {object} options.tracker - Optional tracker (js/common/trackers.js); defaults to the provider this
 *     job run already selected (agents#854), then env/jira.
 * @param {object} [options.config] - Optional project config used to build the tracker when none is passed.
 * @param {object} [options.customParams] - Optional customParams (trackerProvider) for the same purpose.
 * @param {string} options.initiator - Optional initiator account id to mention in the comment.
 * @returns {object} Result summary { posted: number, files: string[], errors: string[] }.
 */
function postTokenUsageComments(ticketKey, options) {
    options = options || {};
    var outputsDir = options.outputsDir || OUTPUTS_DIR;
    var initiator = options.initiator || '';
    var posted = 0;
    var files = [];
    var errors = [];
    var tracker = options.tracker || null;

    var usageFiles = findUsageFiles(outputsDir);
    if (!usageFiles.length) {
        console.log('No token usage files found in ' + outputsDir);
        return { posted: 0, files: [], errors: [] };
    }

    usageFiles.forEach(function(filePath) {
        var data = readJsonFile(filePath);
        if (!data) {
            errors.push(filePath + ' (parse error)');
            return;
        }

        try {
            if (!tracker) tracker = trackersModule.createTracker(resolveConfig(options), options.customParams || {});
            var comment = formatUsageComment(filePath, data, initiator,
                typeof tracker.provider === 'function' ? tracker.provider() : null);
            tracker.postComment(ticketKey, comment);
            console.log('Posted token usage comment for ' + ticketKey + ' from ' + filePath);
            posted += 1;
            files.push(filePath);
        } catch (e) {
            var err = 'Failed to post comment from ' + filePath + ': ' + (e.message || e);
            console.warn(err);
            errors.push(err);
        }
    });

    return { posted: posted, files: files, errors: errors };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        postTokenUsageComments: postTokenUsageComments,
        customParamsOf: customParamsOf,
        findUsageFiles: findUsageFiles,
        formatUsageComment: formatUsageComment,
        avoidBridgeArrayMisparse: avoidBridgeArrayMisparse
    };
}

/**
 * JSRunner entry — mark the machine job done (issue task list). Thin caller
 * for js/factory/mark_job_done.js, the JS port of the awf
 * factory-teammate.yml «Mark machine job done (issue task list)» step
 * (IstiN/dmtools-agentic-workflows#34 scripts/mark-job-done.sh).
 *
 * Invocation (machine-kit / final awf rewire — the sh call becomes):
 *   dmtools run agents/js/factory/run_mark_job_done.json
 *
 * Params resolve customParams first, then the sh step's env names, then the
 * sh defaults — so the same config works from a workflow env block or a
 * fully-materialized runner config. See js/factory/README.md for the full
 * env/file contract.
 *
 * Error contract mirrors the sh under `bash -e`: gh failures PROPAGATE (the
 * step runs under always() and a dead marker flip must redden); the
 * no-marker path is a warning, not an error.
 */

var markJobDone = require('./mark_job_done.js');

/**
 * Env reader for the fallback path. The dmtools JS runtimes do not
 * guarantee a java bridge (GraalJS has one; QuickJS does not), so every
 * access is guarded and missing env simply yields '' — the caller's
 * defaults take over.
 */
function envValue(name) {
    try {
        if (typeof java !== 'undefined' && java && java.lang &&
            java.lang.System && typeof java.lang.System.getenv === 'function') {
            var v = java.lang.System.getenv(name);
            return (v === null || v === undefined) ? '' : String(v);
        }
    } catch (e) { /* no env bridge on this runtime */ }
    return '';
}

/**
 * customParams > env > sh-step defaults. envMap is a test seam (name →
 * value); production passes nothing and reads the process env.
 */
function resolveParams(params, envMap) {
    var custom = (params && params.jobParams && params.jobParams.customParams) || {};
    function env(name) {
        if (envMap && Object.prototype.hasOwnProperty.call(envMap, name)) return envMap[name];
        return envValue(name);
    }
    function pick(key, envName, dflt) {
        var v = custom[key];
        if (v === undefined || v === null || v === '') v = env(envName);
        if (v === undefined || v === null || v === '') v = dflt;
        return v === undefined || v === null ? '' : String(v);
    }
    return {
        number: pick('number', 'NUMBER', ''),
        runUrl: pick('runUrl', 'RUN_URL', ''),
        jobResult: pick('jobResult', 'JOB_RESULT', ''),
        repo: pick('repo', 'GITHUB_REPOSITORY', ''),
        tempPath: pick('tempPath', '', markJobDone.DEFAULT_TEMP_PATH),
        endTs: pick('endTs', '', '')
    };
}

/**
 * JSRunner action. deps is a test seam: production resolves the dmtools
 * globals (cli_execute_command / file_write) exactly like
 * token_usage_publish.js wires its transport.
 */
function action(params, deps) {
    deps = deps || {};
    var exec = deps.cli_execute_command ||
        (typeof cli_execute_command === 'function' ? cli_execute_command : null);
    var write = deps.file_write ||
        (typeof file_write === 'function' ? file_write : null);
    var opts = resolveParams(params, deps.env);
    var result = markJobDone.markJobDone(opts, {
        exec: function (cmd) {
            // Defensive unwrap (token_usage.js execOut pattern): some dmtools
            // runtimes return a result object from cli_execute_command —
            // String(res) would feed '[object Object]' to the flip and
            // silently no-op every marker. No .trim(): the sh consumes the
            // gh body byte-for-byte (trailing newline included) and the
            // awk-port ORS semantics handle the rest.
            var res = exec({ command: cmd });
            return String((res && (res.output || res.stdout)) || res || '');
        },
        writeFile: function (path, content) {
            if (!write) throw new Error('file_write is not available on this runtime');
            return write(path, content);
        },
        clock: function () { return new Date(); },
        log: function (line) { console.log(line); }
    });
    console.log('  ✅ job marker: ' + result.status +
        (result.flipped ? ' (' + result.flipped + ' line(s))' : '') +
        ' — ' + result.mark);
    return result;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue
    };
}

